const pptxgen = require("pptxgenjs");

// Color palette: Midnight Executive with a sharp teal accent
const COLORS = {
  navy: "1E2761",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  teal: "0891B2",
  darkNavy: "0F1535",
  lightGray: "F1F5F9",
  mutedText: "94A3B8",
  coral: "F96167"
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Research Presentation";
pres.title = "Auditing Model Substitution in LLM APIs: Why Software Tests Fail and Hardware Attestation Wins";
pres.subject = "LLM API Integrity, Model Substitution, TEEs";

// Helper to make fresh shadow objects
function makeShadow(opts = {}) {
  return {
    type: "outer",
    color: "000000",
    blur: opts.blur ?? 6,
    offset: opts.offset ?? 2,
    angle: opts.angle ?? 135,
    opacity: opts.opacity ?? 0.15
  };
}

// ==========================================
// SLIDE 1: Title Slide
// ==========================================
let slide1 = pres.addSlide();
slide1.background = { color: COLORS.darkNavy };

// Decorative accent bar on left
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 0.12, h: 5.625,
  fill: { color: COLORS.teal }
});

// Title
slide1.addText("Are You Getting What You Pay For?", {
  x: 0.7, y: 1.4, w: 8.5, h: 0.9,
  fontSize: 40, fontFace: "Arial Black", color: COLORS.white,
  bold: true, align: "left", valign: "middle", margin: 0
});

// Subtitle
slide1.addText("Auditing Model Substitution in LLM APIs: Why Software Tests Fail and Hardware Attestation Wins", {
  x: 0.7, y: 2.3, w: 8.5, h: 1.2,
  fontSize: 20, fontFace: "Arial", color: COLORS.iceBlue,
  align: "left", valign: "top", margin: 0
});

// Tagline box
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0.7, y: 3.6, w: 7.5, h: 0.7,
  fill: { color: COLORS.navy },
  line: { color: COLORS.teal, width: 1.5 }
});
slide1.addText("The trust gap in commercial LLM APIs: providers may covertly swap advertised models for cheaper substitutes.", {
  x: 0.9, y: 3.6, w: 7.1, h: 0.7,
  fontSize: 14, fontFace: "Arial", color: COLORS.white,
  align: "left", valign: "middle", margin: 0
});

// Source citation
slide1.addText("Source: arxiv.org/abs/2504.04715", {
  x: 0.7, y: 4.6, w: 4, h: 0.3,
  fontSize: 11, fontFace: "Arial", color: COLORS.mutedText,
  align: "left", valign: "middle", margin: 0
});

// Audience tag
slide1.addText("ML Researchers  •  AI Security Practitioners  •  Cloud Infrastructure Engineers", {
  x: 0.7, y: 5.0, w: 8, h: 0.3,
  fontSize: 11, fontFace: "Arial", color: COLORS.mutedText,
  align: "left", valign: "middle", margin: 0
});

// ==========================================
// SLIDE 2: The Model Substitution Problem
// ==========================================
let slide2 = pres.addSlide();
slide2.background = { color: COLORS.white };

// Header bar
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 10, h: 0.9,
  fill: { color: COLORS.navy }
});
slide2.addText("The Model Substitution Problem: Economic Incentives Drive Covert Swaps", {
  x: 0.5, y: 0, w: 9, h: 0.9,
  fontSize: 22, fontFace: "Arial Black", color: COLORS.white,
  bold: true, align: "left", valign: "middle", margin: 0
});

// Left column: problem statement
slide2.addText("Core Problem", {
  x: 0.5, y: 1.15, w: 4.2, h: 0.4,
  fontSize: 18, fontFace: "Arial Black", color: COLORS.navy,
  bold: true, align: "left", valign: "middle", margin: 0
});
slide2.addText([
  { text: "Commercial LLM API providers charge for specific models (e.g., Llama-3-70B, Qwen2-72B), but the black-box nature of APIs means users cannot verify the advertised model is actually being served.", options: { breakLine: true } },
  { text: "", options: { breakLine: true } },
  { text: "Providers face strong economic incentives to covertly substitute cheaper alternatives — quantized versions, smaller models, or entirely different architectures — to reduce GPU costs while maintaining pricing.", options: { breakLine: true } }
], {
  x: 0.5, y: 1.55, w: 4.2, h: 2.6,
  fontSize: 13, fontFace: "Arial", color: "334155",
  align: "left", valign: "top", margin: 0
});

// Hypothesis testing box
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 4.1, w: 4.2, h: 1.2,
  fill: { color: COLORS.lightGray },
  line: { color: COLORS.teal, width: 1.5 }
});
slide2.addText("Formal Framework", {
  x: 0.65, y: 4.15, w: 3.9, h: 0.35,
  fontSize: 14, fontFace: "Arial Black", color: COLORS.navy,
  bold: true, align: "left", valign: "middle", margin: 0
});
slide2.addText("H₀: API samples from P_spec(y|x)\nH₁: API samples from P_actual(y|x)", {
  x: 0.65, y: 4.5, w: 3.9, h: 0.7,
  fontSize: 12, fontFace: "Consolas", color: "334155",
  align: "left", valign: "top", margin: 0
