  "Serve an 8B parameter model instead of the advertised 70B.",
  "Replace FP16 weights with FP8 or INT8 quantized versions.",
  "Substitute a modified or updated checkpoint without disclosure.",
  "Serve an entirely different model architecture."
];

for (let i = 0; i < 4; i++) {
  const yPos = 1.15 + i * 1.05;
  // Card background
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: yPos, w: 4.5, h: 0.9,
    fill: { color: COLORS.white },
    line: { color: COLORS.lightGray, width: 1 },
    shadow: makeShadow({ blur: 4, offset: 1, opacity: 0.1 })
  });
  // Accent bar
  slide2.addShape(pres.shapes.RECTANGLE, {
    x: 5.1, y: yPos, w: 0.08, h: 0.9,
    fill: { color: cardColors[i] }
  });
  // Number circle
  slide2.addShape(pres.shapes.OVAL, {
    x: 5.3, y: yPos + 0.25, w: 0.4, h: 0.4,
    fill: { color: cardColors[i] }
  });
  slide2.addText(String(i + 1), {
    x: 5.3, y: yPos + 0.25, w: 0.4, h: 0.4,
    fontSize: 14, fontFace: "Arial Black", color: COLORS.white,
    bold: true, align: "center", valign: "middle", margin: 0
  });
  // Title
  slide2.addText(cardTitles[i], {
    x: 5.85, y: yPos + 0.1, w: 3.5, h: 0.3,
    fontSize: 14, fontFace: "Arial Black", color: COLORS.navy,
    bold: true, align: "left", valign: "middle", margin: 0
  });
  // Description
  slide2.addText(cardDescs[i], {
    x: 5.85, y: yPos + 0.4, w: 3.5, h: 0.45,
    fontSize: 11, fontFace: "Arial", color: "475569",
    align: "left", valign: "top", margin: 0
  });
}

// ==========================================
// SLIDE 3: Quantization Benchmark Drop
